{
  "sop_id": "SOP-020",
  "title": "Leave Applications",
  "steps": [
    {"step_id": "S1", "name": "Create leave ticket and assign to self", "role": "Executor", "type": "intake"},
    {"step_id": "S2", "name": "Check leave balance and eligibility", "role": "Executor", "type": "work"},
    {"step_id": "S3", "name": "Record dates (excluding holidays and weekly offs)", "role": "Executor", "type": "work"},
    {"step_id": "S4", "name": "Submit leave application", "role": "Executor", "type": "work"},
    {"step_id": "A1", "name": "Incharge approval", "role": "Incharge", "type": "approval"},
    {"step_id": "R1", "name": "Correct and resubmit leave application", "role": "Executor", "type": "rework"},
    {"step_id": "A2", "name": "Lead approval (if leave duration > 10 days)", "role": "Lead", "type": "approval"},
    {"step_id": "D1", "name": "Medical certificate (if leave duration > 2 days)", "role": "External", "type": "decision"},
    {"step_id": "D2", "name": "Negative balance (allowed only as loss of pay)", "role": "System", "type": "decision"}
  ],
  "approvals": [
    {"stage": "Incharge", "condition": "always"},
    {"stage": "Lead", "condition": "leave duration > 10 days"}
  ],
  "dependencies": [
    {"dep_id": "D1", "provider": "Employee", "item": "Medical certificate", "parallel_group": "P1"},
    {"dep_id": "D2", "provider": "System", "item": "Negative balance check", "parallel_group": ""}
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
